func maybeInjectMemoryLoop(ctx context.Context, ag agent.Agent, event *agent.Event) error {
	if event.Prompt == "" {
		return nil
	}

	writer, ok := agent.AsHookResponseWriter(ag)
	if !ok {
		return nil
	}

	state, loadErr := memoryloop.LoadState(ctx)
	if loadErr != nil {
		state = &memoryloop.State{}
	}
	settingsValue, settingsErr := LoadEntireSettings(ctx)
	if settingsErr != nil {
		settingsValue = nil
	}
	mode := effectiveMemoryLoopMode(state, settingsValue)
	debug := effectiveMemoryLoopDebug(state, settingsValue)
	if state.Snapshot == nil {
		return nil
	}

	now := time.Now().UTC()
	selectOpts := buildMemoryLoopSelectOpts(ctx, state.Snapshot)
	report := memoryloop.PreviewSelection(*state.Snapshot, event.Prompt, now, selectOpts...)
	if len(report.Matches) == 0 {
		if debug {
			if err := writer.WriteHookResponse(buildMemoryLoopDebugPrompt(event.Prompt, report)); err != nil {
				return fmt.Errorf("failed to write memory-loop debug prompt: %w", err)
			}
		}
		return nil
	}
	matches := report.Matches

	switch mode {
	case memoryloop.ModeManual:
		if !supportsManualMemoryPrompt(ag.Name()) {
			return nil
		}
		if err := writer.WriteHookResponse(buildManualMemoryPrompt(matches)); err != nil {
			return fmt.Errorf("failed to write manual memory prompt: %w", err)
		}
		return nil
	case memoryloop.ModeAuto:
		if string(ag.Name()) != memoryLoopClaudeAgentName || !state.Snapshot.InjectionEnabled {
			return nil
		}
	default:
		return nil
	}

	message := memoryloop.FormatInjectionBlock(matches)
	if strings.TrimSpace(event.ResponseMessage) != "" {
		message = strings.TrimSpace(event.ResponseMessage) + "\n\n" + message
	}
	if err := writer.WriteHookResponse(message); err != nil {
		return fmt.Errorf("failed to write memory-loop hook response: %w", err)
	}

	ids := make([]string, 0, len(matches))
	reasons := make([]string, 0, len(matches))
	for _, match := range matches {
		ids = append(ids, match.Record.ID)
		if match.Reason != "" {
			reasons = append(reasons, match.Reason)
		}
	}

	logEntry := memoryloop.InjectionLog{
		SessionID:         event.SessionID,
		PromptPreview:     truncatePromptPreview(event.Prompt, 500),
		InjectedMemoryIDs: ids,
		InjectedAt:        now,
		Reason:            strings.Join(reasons, ", "),
	}
	memoryloop.RecordInjectionActivity(state, matches, logEntry, now)
	if err := memoryloop.SaveState(ctx, state); err != nil {
		logging.Warn(logging.WithComponent(ctx, "lifecycle"), "failed to persist memory-loop injection activity",
